import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, float, vec2, sin, fract, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'hub-collection-card-0-label';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? {
      text: 'Collection 3',
      typography: { fontSize: 39 },
    };

  // ---- Card plaque (machined-metal PBR plane) ----
  const cardW = 1.6;
  const cardH = 0.5;
  const cardGeo = new THREE.PlaneGeometry(cardW, cardH, 1, 1);

  const uvNode = uv();
  const hash = fract(
    sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const roughnessNode = float(0.55).add(hash.mul(0.06));
  const metalnessNode = float(0.4);
  const clearcoatNode = float(0.15);

  const cardMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.ink),
    side: THREE.FrontSide,
  });
  cardMat.roughnessNode = roughnessNode;
  cardMat.metalnessNode = metalnessNode;
  cardMat.clearcoatNode = clearcoatNode;
  cardMat.clearcoatRoughness = 0.3;

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.name = 'label-plaque';
  group.add(cardMesh);

  // texture load (async, cached loader)
  let loadedTex = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTex = tex;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    })
    .catch(() => {
      /* fallback: keep flat ink color */
    });

  // ---- Accent underline strip (thin PBR bar) ----
  const accentGeo = new THREE.PlaneGeometry(cardW * 0.75, 0.035, 1, 1);
  const accentMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.accent),
  });
  const accentMesh = new THREE.Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -cardH / 2 + 0.05, 0.01);
  group.add(accentMesh);

  // ---- Text: headline label ----
  const fontSizePx = headlineItem.typography?.fontSize ?? 39;
  const textObj = ctx.fontAtlas.createText(headlineItem.text ?? 'Collection 3', {
    fontSize: fontSizePx,
    color: colors.paper,
    align: 'center',
  });
  textObj.position.set(0, 0.02, 0.02);
  textObj.scale.setScalar(0.01);
  group.add(textObj);

  // ---- Local rim/accent light (node-local, per-card) ----
  const rimLight = new THREE.DirectionalLight(
    new THREE.Color(colors.accent),
    0.7
  );
  rimLight.position.set(-1.2, 0.6, 1.4);
  group.add(rimLight);

  // ---- Scene placement (rotation/scale explicit; position applied by adapter) ----
  const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
  group.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  const scl = config.scale ?? { x: 1, y: 1, z: 1 };
  group.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  // ---- Weighted entrance settle (static composition otherwise) ----
  group.position.y += 0.18;
  cardMat.opacity = 1;
  cardMesh.scale.setScalar(0.98);
  accentMesh.scale.setScalar(0.98);

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: group.position.y - 0.18,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    [cardMesh.scale, accentMesh.scale],
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    },
    0.05
  );

  // no interactivity per spec — empty handler map maintained for contract
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(cardMesh.scale);
    gsap.killTweensOf(accentMesh.scale);

    cardGeo.dispose();
    cardMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();

    if (loadedTex && loadedTex.dispose) {
      loadedTex.dispose();
    }

    if (textObj.geometry) textObj.geometry.dispose?.();
    if (textObj.material) textObj.material.dispose?.();

    group.remove(rimLight);
    group.remove(textObj);
    group.remove(accentMesh);
    group.remove(cardMesh);
  };

  return group;
}
